package com.giftmarket.admin.dto.response;import com.giftmarket.order.entity.*;import com.giftmarket.payment.entity.*;import java.time.LocalDateTime;import java.util.List;
public record AdminReturnDetailResponse(Long returnId,ReturnRequestStatus status,ReturnReasonType reasonType,String reason,ReturnResponsibility responsibility,String rejectedReason,LocalDateTime requestedAt,LocalDateTime approvedAt,LocalDateTime collectingAt,LocalDateTime receivedAt,LocalDateTime inspectedAt,LocalDateTime refundingAt,LocalDateTime completedAt,LocalDateTime rejectedAt,LocalDateTime canceledAt,LocalDateTime failedAt,OrderInfo order,Buyer buyer,SellerInfo seller,List<Item> items,List<Evidence> evidence,CollectionInfo collection,RefundCalculation refundCalculation,PaymentInfo payment,PaymentCancellationInfo paymentCancellation){
 public record OrderInfo(Long orderId,String orderNumber,OrderStatus status,LocalDateTime orderedAt){}public record Buyer(Long userId,String name,String email){}public record SellerInfo(Long sellerOrderId,SellerOrderStatus status,Long sellerId,String storeName){}
 public record Item(Long returnRequestItemId,Long orderItemId,Long productId,String productName,String optionSnapshot,Long unitPrice,int originalQuantity,int returnQuantity,int returnedQuantity,ReturnInspectionResult inspectionResult,int restockedQuantity){public static Item from(ReturnRequestItem ri){var i=ri.getOrderItem();return new Item(ri.getId(),i.getId(),i.getProduct().getId(),i.getProductName(),i.getOptionSnapshot(),i.getUnitPrice(),i.getQuantity(),ri.getQuantity(),i.getReturnedQuantity(),ri.getInspectionResult(),ri.getRestockedQuantity());}}
 public record Evidence(Long imageId,String url,int sortOrder){}public record CollectionInfo(Long shipmentId,ShipmentType type,ShipmentStatus status,String shippingCompany,String trackingNumber,LocalDateTime shippedAt,LocalDateTime deliveredAt){}
 public record RefundCalculation(Long productRefundAmount,Long originalShippingRefundAmount,Long returnShippingCharge,Long refundAmount){}public record PaymentInfo(Long paymentId,PaymentStatus status,Long originalAmount,long succeededRefundAmount){}
 public record PaymentCancellationInfo(Long paymentCancellationId,PaymentCancellationType type,PaymentCancellationStatus status,Long amount,LocalDateTime requestedAt,LocalDateTime canceledAt,LocalDateTime failedAt,String failureCode){public static PaymentCancellationInfo from(PaymentCancellation p){return p==null?null:new PaymentCancellationInfo(p.getId(),p.getType(),p.getStatus(),p.getAmount(),p.getRequestedAt(),p.getCanceledAt(),p.getFailedAt(),p.getFailureCode());}}
}
